.doc-create-actions{display:flex;flex-wrap:wrap;gap:8px;justify-content:flex-end}.doc-create-actions .btn{white-space:nowrap}.notice.success{margin:0 0 16px;padding:12px 16px;border-radius:12px;background:#ecfdf3;color:#137333;font-weight:700}.doc-actions{white-space:normal;min-width:300px}.doc-actions .btn,.doc-actions form,.doc-actions select{margin:3px}.doc-mail-modal[hidden]{display:none}.doc-mail-modal{position:fixed;inset:0;z-index:9999;overflow:auto;padding:16px}.doc-mail-backdrop{position:absolute;inset:0;background:rgba(7,20,45,.45);backdrop-filter:blur(3px)}.doc-mail-card{position:relative;width:min(720px,100%);max-height:calc(100dvh - 32px);margin:4vh auto 0;background:#fff;border-radius:20px;padding:24px;box-shadow:0 25px 70px rgba(10,30,70,.25);overflow:auto}.doc-mail-head{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:14px}.doc-mail-card h2{margin:0 0 5px}.doc-mail-card label{display:block;font-weight:800;margin:10px 0 6px}.doc-mail-card input,.doc-mail-card textarea{width:100%;box-sizing:border-box;border:1px solid #d8e1ee;border-radius:12px;padding:10px 12px;font:inherit}.doc-mail-card textarea{resize:vertical;line-height:1.5;min-height:180px;max-height:38dvh}.mail-note{font-size:12px;color:#718096;margin-top:8px}.doc-mail-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:16px;position:sticky;bottom:-1px;background:#fff;padding-top:10px}.doc-mail-actions .btn{min-width:130px}@media(max-width:760px){.doc-create-actions{justify-content:flex-start}.doc-actions{min-width:0}.doc-mail-modal{padding:8px}.doc-mail-card{width:100%;max-height:calc(100dvh - 16px);margin:0;padding:16px;border-radius:16px}.doc-mail-card textarea{min-height:120px;max-height:30dvh}.doc-mail-actions{display:grid;grid-template-columns:1fr 1fr}.doc-mail-actions .btn{width:100%;min-width:0}.doc-mail-head{margin-bottom:8px}.doc-mail-card h2{font-size:20px}}@media(max-width:430px){.doc-mail-actions{grid-template-columns:1fr}.doc-mail-card textarea{max-height:26dvh}}
