<script>
(()=>{const modal=document.getElementById('payModal'),form=document.getElementById('payForm'),amount=document.getElementById('payAmount'),meta=document.getElementById('payMeta');
document.querySelectorAll('.pay-doc').forEach(b=>b.addEventListener('click',()=>{const total=parseFloat(b.dataset.total||'0'),paid=parseFloat(b.dataset.paid||'0'),remaining=Math.max(0,total-paid);form.action='/documents/'+b.dataset.id+'/pay';amount.value=remaining.toFixed(2);amount.max=remaining.toFixed(2);meta.textContent='Faktura '+b.dataset.number+' · zbývá '+remaining.toFixed(2)+' Kč';modal.hidden=false;}));
document.querySelectorAll('[data-close-pay]').forEach(x=>x.addEventListener('click',()=>modal.hidden=true));
})();
</script>
<script>
(()=>{const modal=document.getElementById('sendModal'),form=document.getElementById('sendMailForm'),subject=document.getElementById('mailSubject'),body=document.getElementById('mailBody'),meta=document.getElementById('mailMeta');
const templates={invoice:['Faktura','Dobrý den,\n\nv příloze Vám zasíláme fakturu.\n\nS pozdravem,'],proforma:['Zálohová faktura','Dobrý den,\n\nv příloze Vám zasíláme zálohovou fakturu.\n\nS pozdravem,'],offer:['Nabídka','Dobrý den,\n\nv příloze Vám zasíláme nabídku.\n\nS pozdravem,'],order:['Objednávka','Dobrý den,\n\nv příloze Vám zasíláme objednávku.\n\nS pozdravem,'],credit:['Dobropis','Dobrý den,\n\nv příloze Vám zasíláme dobropis.\n\nS pozdravem,']};
document.querySelectorAll('.send-doc').forEach(b=>b.addEventListener('click',()=>{const t=templates[b.dataset.type]||['Doklad','Dobrý den,\n\nv příloze Vám zasíláme doklad.\n\nS pozdravem,'];const num=b.dataset.number;subject.value=t[0]+' č. '+num+' – Byznio';body.value=t[1]+'\nByznio';meta.textContent='Doklad '+num+(b.dataset.email?' · '+b.dataset.email:' · zákazník nemá vyplněný e-mail');form.action='/documents/'+b.dataset.id+'/send-email';modal.hidden=false;}));
document.querySelectorAll('[data-close-mail]').forEach(x=>x.addEventListener('click',()=>modal.hidden=true));
})();
</script>
